import {backend} from './backend.js';
import {escape as e} from './store.js';
let users=[],total=0,offset=0,query='',error='',loading=false,mailHistory=[],mailError='',configured=false,sending=false,stop=false;
export function resetUsers(){users=[];total=0;offset=0;query='';error='';mailHistory=[];mailError='';configured=false;stop=true;}
async function load(ui){const owner=backend.user()?.id;loading=true;error='';ui.render();try{const result=await backend.adminUsers(offset,query);if(backend.user()?.id!==owner)return;users=result.users;total=result.total;}catch(err){error=err.message;}finally{loading=false;ui.render();}}
export function usersScreen(){return `<section class="card"><div class="card-head"><h2>Registered users</h2><span class="pill">${total} accounts</span></div><form id="users-search-form" class="toolbar"><input name="query" aria-label="Search registered users" maxlength="100" placeholder="Search name, username, phone or email" value="${e(query)}"><button class="btn">Search</button></form><p class="muted">Disable blocks protected content and future logins. Delete permanently removes the account and its linked LexAmah profile and quiz results. Administrator accounts are protected.</p>${error?`<p role="alert">${e(error)} · Run user-management.sql, then refresh.</p>`:''}${loading?'<p role="status">Loading users…</p>':users.map(u=>`<article class="user-record"><div><strong>${e(u.full_name)}</strong><p>@${e(u.username)} · ${e(u.disabled?'Disabled':'Active')}${u.is_admin?' · Administrator':''}</p><p>Email: ${e(u.email||'—')}<br>Phone: ${e(u.phone_number||'Not provided')}<br>${e(u.institution)} · ${e(u.level)}</p></div><div class="actions">${u.is_admin?'':`<button class="btn" data-user-action="${u.disabled?'enable':'disable'}" data-user-id="${e(u.user_id)}">${u.disabled?'Re-enable':'Disable'}</button><button class="btn danger" data-user-action="delete" data-user-id="${e(u.user_id)}">Delete</button>`}</div></article>`).join('')||'<p class="muted">No matching accounts.</p>'}<div class="actions"><button class="btn" id="users-prev" ${offset===0||loading?'disabled':''}>Previous</button><span>${total?offset+1:0}–${Math.min(offset+50,total)} of ${total}</span><button class="btn" id="users-next" ${offset+50>=total||loading?'disabled':''}>Next</button><button class="btn" id="users-refresh">Refresh users</button></div></section>`;}
export function mailScreen(){return `<section class="card"><div class="card-head"><h2>Email registered users</h2><button class="btn" id="mail-refresh">Refresh history</button></div><p class="muted">Send platform announcements to active accounts with confirmed email addresses. Each recipient receives an individual email. Keep this page open while sending; you can resume from history.</p>${mailError?`<p role="alert">${e(mailError)}</p>`:''}${configured?'':'<div class="notice">Before sending, add RESEND_API_KEY and LEXAMAH_MAIL_FROM to Supabase Edge Function secrets. Your sender domain must be verified in Resend.</div>'}<form id="mail-compose"><label for="mail-subject">Subject</label><input id="mail-subject" name="subject" required maxlength="180"><label for="mail-message">Message</label><textarea id="mail-message" name="message" rows="10" required maxlength="8000" placeholder="Write your announcement…"></textarea><p id="mail-compose-status" role="status"></p><button class="btn primary" ${sending?'disabled':''}>Review recipients & message</button></form></section><section class="card"><h2>Recent messages</h2>${mailHistory.map(j=>`<div class="row"><div class="row-copy"><strong>${e(j.subject)}</strong><small>${e(new Date(j.created_at).toLocaleString())}</small></div><button class="btn" data-mail-open="${e(j.id)}" ${sending?'disabled':''}>View / resume</button></div>`).join('')||'<p class="muted">No messages loaded. Refresh history to check.</p>'}</section>`;}
async function history(ui){mailError='';try{const data=await backend.adminMail({action:'history'});if(!backend.adminReady())return;mailHistory=data.jobs;configured=data.configured;}catch(err){mailError=err.message;}ui.render();}
function review(data,ui){const {job,counts}=data;ui.modal('Review bulk email',`<p><strong>${e(job.subject)}</strong></p><p class="mail-preview">${e(job.message)}</p><p id="mail-progress" role="status">${summary(counts)}</p>${(data.errors||[]).map(x=>`<p>${e(x.email)}: ${e(x.error)}</p>`).join('')}<p class="muted">Sent means accepted by the email provider; delivery can be checked in Resend. Resuming retries pending recipients only. Resume within 23 hours.</p><div class="actions"><button class="btn primary" id="mail-send" ${!counts.pending?'disabled':''}>${counts.sent?'Resume pending':'Send to '+counts.pending+' recipients'}</button><button class="btn" id="mail-close">Close</button></div>`);
 document.querySelector('#dialog').addEventListener('close',()=>{stop=true;},{once:true});
 document.querySelector('#mail-close').onclick=()=>{stop=true;document.querySelector('#dialog').close();};
 document.querySelector('#mail-send').onclick=async ev=>{if(sending)return;sending=true;stop=false;ev.target.disabled=true;const status=document.querySelector('#mail-progress');try{let current=data;while(!stop&&current.counts.pending){status.textContent=summary(current.counts)+' · Sending…';current=await backend.adminMail({action:'send',job_id:job.id});status.textContent=summary(current.counts)+(current.paused?' · '+current.paused:'');if(current.paused)break;}if(!current.counts.pending)status.textContent=summary(current.counts)+' · Finished.';ev.target.disabled=!current.counts.pending;ev.target.textContent='Resume pending';}catch(err){status.textContent=err.message;ev.target.disabled=false;ev.target.textContent='Resume pending';}finally{sending=false;}};
}
function summary(c){return `${c.total} recipients · ${c.sent} accepted · ${c.pending} pending · ${c.failed} failed · ${c.skipped} skipped`;}
function accountAction(action,id,ui){const user=users.find(u=>u.user_id===id);if(!user)return;ui.modal(`${action==='delete'?'Delete permanently':action==='disable'?'Disable account':'Re-enable account'}?`,`<p>${e(user.full_name)} (@${e(user.username)})</p><p class="muted">${action==='delete'?'This permanently deletes the account and linked LexAmah profile and quiz results. Downloads already saved on their device remain. Type the username to confirm.':action==='disable'?'This blocks account access to protected content. Existing downloaded files and previously signed audio links remain accessible until those links expire.':'This restores account access.'}</p><form id="account-action-form">${action==='delete'?'<label for="delete-username">Username</label><input id="delete-username" name="confirm" autocomplete="off" required>':''}<p id="account-action-status" role="status"></p><div class="actions"><button class="btn ${action==='delete'?'danger':'primary'}">Confirm ${e(action)}</button><button type="button" class="btn" id="account-cancel">Cancel</button></div></form>`);document.querySelector('#account-cancel').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#account-action-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{await backend.adminAccount(action,id,new FormData(ev.target).get('confirm')||'');document.querySelector('#dialog').close();await load(ui);ui.toast('Account updated.');}catch(err){document.querySelector('#account-action-status').textContent=err.message;button.disabled=false;}};}
export function bindUsers(ui){const f=document.querySelector('#users-search-form');if(f)f.onsubmit=ev=>{ev.preventDefault();query=new FormData(ev.target).get('query').trim();offset=0;load(ui);};const compose=document.querySelector('#mail-compose');if(compose)compose.onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const values=Object.fromEntries(new FormData(ev.target));const data=await backend.adminMail({action:'prepare',job_id:crypto.randomUUID(),...values});review(data,ui);}catch(err){document.querySelector('#mail-compose-status').textContent=err.message;}finally{button.disabled=false;}};}
export async function usersClick(button,ui){if(button.dataset.userAction){accountAction(button.dataset.userAction,button.dataset.userId,ui);return true;}if(['users-prev','users-next','users-refresh'].includes(button.id)){offset=button.id==='users-prev'?Math.max(0,offset-50):button.id==='users-next'?offset+50:offset;await load(ui);return true;}if(button.id==='mail-refresh'){await history(ui);return true;}if(button.dataset.mailOpen){try{review(await backend.adminMail({action:'status',job_id:button.dataset.mailOpen}),ui);}catch(err){ui.toast(err.message);}return true;}return false;}
export async function loadUsersTab(tab,ui){if(tab==='users')await load(ui);if(tab==='mail')await history(ui);}
